import { inject, Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, map, shareReplay } from 'rxjs';
import { PostalCode } from '../utils/postal-code-search';

// Every Swiss NPA and its towns, from swisstopo's official directory of
// localities - a static file (public/data, regenerated by
// scripts/generate-swiss-postal-codes.mjs), not an API: ~90kB fetched once,
// the first time an address form needs it, then kept for the session.
@Injectable({ providedIn: 'root' })
export class PostalCodeService {

  private http = inject(HttpClient);

  readonly codes$: Observable<PostalCode[]> = this.http.get<[string, string][]>('/data/swiss-postal-codes.json').pipe(
    map(rows => rows.map(([npa, town]) => ({ npa, town }))),
    shareReplay(1),
  );
}
